from taf.gnb.oam.ne3s.ws.components.SWM.v1.resources.notifications.messages import SWMNotificationGroup
from taf.gnb.oam.ne3s.ws.components.CM.v1.resources.notifications.messages import CMNotificationGroup
from taf.gnb.oam.ne3s.ws.components.FM.v1.resources.notifications.messages import FMNotificationGroup
from taf.gnb.oam.ne3s.ws.components.ATL.v1.resources.notifications.messages import ATLNotificationGroup
from taf.gnb.oam.ne3s.ws.components.PM.v1.resources.notifications.messages import PMNotificationGroup
from taf.gnb.oam.ne3s.ws.components.CERT.v1.resources.notifications.messages import CertNotificationGroup
from taf.gnb.oam.ne3s.ws.components.UM.v1.resources.notifications.messages import UMNotificationGroup


class NotificationPool(object):
    NOTIFICATION_GROUPS = (
        SWMNotificationGroup,
        CertNotificationGroup,
        PMNotificationGroup,
        ATLNotificationGroup,
        FMNotificationGroup,
        CMNotificationGroup,
        UMNotificationGroup
    )

    @classmethod
    def get_notification_groups(cls, queue_id):
        """ Calculate factories that are interested in this notification.
        If queue_id is None, all factories are notified. """
        if queue_id:
            groups = [group for group in cls.NOTIFICATION_GROUPS
                      if queue_id in group.QUEUE_IDS]
        else:
            groups = cls.NOTIFICATION_GROUPS

        return groups
